  --shadow-focus-error: 0 0 0 3px rgba(240, 82, 82, 0.3);
  --transition: 150ms ease;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

body {
  min-height: 100vh;
  background: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem;
  line-height: 1.6;
}

header {
  width: 100%;
  max-width: 540px;
  margin-bottom: 2rem;
  text-align: center;
}

header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

header p {
  margin-top: 0.4rem;
  color: var(--color-text-secondary);
  font-size: 0.95rem;
}

main {
  width: 100%;
  max-width: 540px;
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem 2rem 2.25rem;
  box-shadow: var(--shadow-card);
}

/* Form */
.contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-primary);
  letter-spacing: 0.01em;
}

.required-indicator {
  color: #f87171;
  margin-left: 0.15em;
  aria-hidden: true;
}

input {
  background: var(--color-surface-raised);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
  font-size: 1rem;
  font-family: var(--font);
  padding: 0.625rem 0.875rem;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
  outline: none;
  width: 100%;
}

input::placeholder {
  color: var(--color-text-placeholder);
}

input:hover:not(:disabled) {
  border-color: #3d4470;
}

input:focus {
  border-color: var(--color-border-focus);
  box-shadow: var(--shadow-focus);
  outline: 3px solid transparent;
}

input[aria-invalid="true"] {
  border-color: var(--color-border-error);
  background: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  box-shadow: var(--shadow-focus-error);
}

.field-help {
  font-size: 0.8rem;
  color: var(--color-text-secondary);
}

.field-error {
  font-size: 0.8rem;
  color: var(--color-error);
  display: none;
  align-items: center;
  gap: 0.3em;
}

.field-error[aria-hidden="false"],
.field-error:not([aria-hidden]) {
  display: flex;
}

.field-error svg {
  flex-shrink: 0;
}

/* Submit button */
.submit-btn {
  margin-top: 0.4rem;
  padding: 0.7rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition), transform 80ms ease;
  outline: none;
  align-self: flex-start;
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--color-accent-hover);
}

.submit-btn:active {
  background: var(--color-accent-active);
  transform: translateY(1px);
}

.submit-btn:focus-visible {
  box-shadow: var(--shadow-focus);
  outline: 3px solid transparent;
}

/* Success banner */
.success-banner {
  display: none;
  align-items: center;
  gap: 0.75rem;
  background: rgba(52, 211, 153, 0.1);
  border: 1px solid rgba(52, 211, 153, 0.3);
  border-radius: var(--radius-md);
  padding: 0.875rem 1rem;
  color: #34d399;
  font-size: 0.95rem;
  font-weight: 500;
  margin-top: 1rem;
}

.success-banner[aria-hidden="false"] {
  display: flex;
}

/* Forced colors / high contrast */
@media (forced-colors: active) {
  input {
    border: 1.5px solid ButtonBorder;
    background: Canvas;
    color: CanvasText;
  }
  input:focus {
    outline: 3px solid Highlight;
    box-shadow: none;
  }
  .submit-btn {
    border: 2px solid ButtonBorder;
    background: ButtonFace;
    color: ButtonText;
    forced-color-adjust: none;
  }
  .submit-btn:focus-visible {
    outline: 3px solid Highlight;
    box-shadow: none;
  }
  .field-error {
    color: LinkText;
  }
}

/* Reflow at 320px */
@media (max-width: 400px) {
  .card {
    padding: 1.25rem 1rem 1.5rem;
  }
  header h1 {
    font-size: 1.4rem;
  }
}
